using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Query; using Xunit;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Query;
public sealed class AstronomyKnowledgePayloadFamilyFilterTests{[Fact]public void Constructs_and_normalizes(){var caller=new List<AstronomyKnowledgePayloadFamily>{AstronomyKnowledgePayloadFamily.SpatialPosition,AstronomyKnowledgePayloadFamily.PhysicalProperty,AstronomyKnowledgePayloadFamily.PhysicalProperty};var f=new AstronomyKnowledgePayloadFamilyFilter(caller);caller.Add(AstronomyKnowledgePayloadFamily.SpatialPosition);Assert.Equal(AstronomyKnowledgeQueryMatchMode.Any,f.MatchMode);Assert.Equal(new[]{AstronomyKnowledgePayloadFamily.PhysicalProperty,AstronomyKnowledgePayloadFamily.SpatialPosition},f.Values);Assert.Throws<NotSupportedException>(()=>((IList<AstronomyKnowledgePayloadFamily>)f.Values).Add(AstronomyKnowledgePayloadFamily.PhysicalProperty));}[Fact]public void Supports_all_mode(){var f=new AstronomyKnowledgePayloadFamilyFilter([AstronomyKnowledgePayloadFamily.PhysicalProperty],AstronomyKnowledgeQueryMatchMode.All);Assert.Equal(AstronomyKnowledgeQueryMatchMode.All,f.MatchMode);}[Fact]public void Rejects_invalid_inputs(){Assert.Throws<ArgumentException>(()=>new AstronomyKnowledgePayloadFamilyFilter([]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgePayloadFamilyFilter([(AstronomyKnowledgePayloadFamily)99]));Assert.Throws<ArgumentOutOfRangeException>(()=>new AstronomyKnowledgePayloadFamilyFilter([AstronomyKnowledgePayloadFamily.PhysicalProperty],(AstronomyKnowledgeQueryMatchMode)99));}}
